Now I'll synthesize the complete design document for the unified golden case schema:

---

## CANONICAL UNIFIED GOLDEN TEST CASE SCHEMA

### EXECUTIVE SUMMARY

**Problem:** Three disjoint eval systems with different semantics:
- **System A (Go literals)** — 55 cases in `regression_test.go`, `evaluateTestCase()` tautological (always returns Pass:true)
- **System B (JSON golden)** — 93 actual cases in `golden_datasets/*/*.json`, has pre-baked `actual_output` + `evaluation_results` (orphaned—zero Go code loads it)
- **System C (Runnable harnesses)** — `singleturn/` (13 cases), `multiturn/` (5 cases), real Ollama/agent execution, NOT wired into gates

**Root cause:** No single source of truth; `expected` conflates template vs. runtime; no real evaluator connected.

**Solution:** Design a canonical `pkg/eval/golden` package with:
1. One Go type hierarchy (`Case`, `Dataset`)
2. Single JSON disk format (no pre-baked `actual_output`)
3. Honest `LoadGoldenDir()` loader
4. Evaluation function that **can fail** (calls real judges)
5. Migration recipe for 55 Go literals + 93 JSON cases → unified format

---

## (1) GO TYPE DEFINITIONS: `pkg/eval/golden/types.go`

```go
// Package golden provides canonical test case definitions and disk I/O
// for unified evaluation of Genie multi-agent platform.
//
// A Case is the minimal unit: one scenario with input, rubric references,
// and an expected outcome template. No pre-baked actual_output.
// At evaluation time, a real Judge compares actual runtime output to expected.
//
// A Dataset is a named collection of Cases (e.g., "settlement/correct").
// LoadGoldenDir() discovers and parses all domain files into a registry.
package golden

import (
	"time"
)

// Case represents one test scenario in the canonical golden dataset.
// It is a SOURCE OF TRUTH with no pre-baked actual_output.
// Input + Expected are templates; actual execution produces runtime values.
type Case struct {
	// ID unique identifier (e.g., "TC-FM-SE-001-001" or "SE-CORRECT-001").
	// Format: TC-<DOMAIN>-<INDEX> or <DOMAIN>-<CATEGORY>-<INDEX>
	ID string `json:"id"`

	// FailureMode maps to failure_modes.json entry (e.g., "FM-SE-001").
	// Use "none" for happy-path cases.
	FailureMode string `json:"failure_mode"`

	// RubricRefs list of rubric IDs used to evaluate this case
	// (e.g., ["RB-SE-001", "RB-SE-002"]).
	// Empty list means case is descriptive only (no evaluation expected).
	RubricRefs []string `json:"rubric_refs"`

	// Scenario human-readable test description (1-2 sentences).
	Scenario string `json:"scenario"`

	// Input is a map of parameters used to construct or run the test.
	// Keys/values are arbitrary but should be deterministic.
	// Example: {order_id: "ORD-001", amount_paise: 50000, timestamp: "2026-06-07T10:00:00Z"}
	Input map[string]interface{} `json:"input"`

	// Expected is the template outcome for a **passing** execution.
	// Keys match runtime output structure (from actual_output in evaluation).
	// Values are either:
	//   - Exact matches (e.g., settlement_result: "success")
	//   - Patterns (e.g., merchant_balance: {match_type: "greater_than", value: 0})
	//   - Absence checks (e.g., error_code: null)
	// NO pre-baked values; only schema and assertions.
	Expected map[string]interface{} `json:"expected"`

	// ExecutionTrace optional ordered list of steps taken during test.
	// Set only if case is pre-executed (e.g., from JSON golden files);
	// otherwise populated at runtime. Used for auditing and lineage.
	ExecutionTrace []string `json:"execution_trace,omitempty"`

	// Metadata contextual tags (domain, severity, category, etc.).
	Metadata map[string]string `json:"metadata"`

	// CreatedAt timestamp when case was added to golden dataset.
	CreatedAt time.Time `json:"created_at"`

	// Source indicates provenance: "regression_test" (System A), "json_golden" (System B),
	// "hardness" (from harness), or empty for new cases.
	Source string `json:"source,omitempty"`
}

// Dataset is a named collection of Cases for a single domain/category.
// Example: domain="settlement", category="correct" → settlement/correct_cases.json
// Maps to golden_datasets/INDEX.json domain/category structure.
type Dataset struct {
	// Domain system area (settlement, compliance, orchestration, lineage).
	Domain string `json:"domain"`

	// Category test classification (correct, hallucination, netting, edge_regression, etc.).
	Category string `json:"category"`

	// Description human-readable dataset purpose.
	Description string `json:"description"`

	// Cases list of test cases in this dataset.
	Cases []Case `json:"cases"`

	// TotalCases count of cases in this dataset.
	TotalCases int `json:"total_cases"`

	// FailureModesCovered list of FM-* IDs referenced by at least one case.
	FailureModesCovered []string `json:"failure_modes_covered,omitempty"`

	// RubricsCovered list of RB-* IDs referenced by at least one case.
	RubricsCovered []string `json:"rubrics_covered,omitempty"`

	// CreatedAt timestamp when dataset was created.
	CreatedAt time.Time `json:"created_at"`
}

// Registry holds all loaded datasets, indexed by (domain, category).
type Registry struct {
	// ByDomainCategory maps "settlement:correct" -> Dataset
	ByDomainCategory map[string]*Dataset

	// ByCaseID maps "TC-FM-SE-001-001" -> *Case (cross-dataset lookup)
	ByCaseID map[string]*Case

	// AllCases flattened list of all cases across all datasets.
	AllCases []Case

	// LoadedAt timestamp when registry was loaded from disk.
	LoadedAt time.Time
}

// NewRegistry creates an empty registry.
func NewRegistry() *Registry {
	return &Registry{
		ByDomainCategory: make(map[string]*Dataset),
		ByCaseID:         make(map[string]*Case),
		AllCases:         []Case{},
		LoadedAt:         time.Now(),
	}
}

// Add registers a dataset in the registry.
// Panics if case IDs conflict (not idempotent).
func (r *Registry) Add(ds *Dataset) error {
	key := ds.Domain + ":" + ds.Category
	if _, exists := r.ByDomainCategory[key]; exists {
		return fmt.Errorf("dataset already registered: %s", key)
	}

	r.ByDomainCategory[key] = ds

	for i := range ds.Cases {
		caseRef := &ds.Cases[i]
		if _, exists := r.ByCaseID[caseRef.ID]; exists {
			return fmt.Errorf("case ID conflict: %s", caseRef.ID)
		}
		r.ByCaseID[caseRef.ID] = caseRef
		r.AllCases = append(r.AllCases, *caseRef)
	}

	return nil
}

// GetByID looks up a case by ID across all datasets.
func (r *Registry) GetByID(id string) *Case {
	return r.ByCaseID[id]
}

// GetDataset retrieves a dataset by domain:category key.
func (r *Registry) GetDataset(domain, category string) *Dataset {
	return r.ByDomainCategory[domain+":"+category]
}

// AllByFailureMode returns all cases referencing a given FM-* ID.
func (r *Registry) AllByFailureMode(fmID string) []Case {
	var result []Case
	for _, c := range r.AllCases {
		if c.FailureMode == fmID {
			result = append(result, c)
		}
	}
	return result
}

// AllByRubric returns all cases referencing a given RB-* ID.
func (r *Registry) AllByRubric(rbID string) []Case {
	var result []Case
	for _, c := range r.AllCases {
		for _, ref := range c.RubricRefs {
			if ref == rbID {
				result = append(result, c)
				break
			}
		}
	}
	return result
}

// AllByDomain returns all cases in a domain.
func (r *Registry) AllByDomain(domain string) []Case {
	var result []Case
	for _, c := range r.AllCases {
		if c.Metadata["domain"] == domain {
			result = append(result, c)
		}
	}
	return result
}

// Stats returns coverage statistics.
func (r *Registry) Stats() map[string]interface{} {
	fmCounts := make(map[string]int)
	rbCounts := make(map[string]int)

	for _, c := range r.AllCases {
		if c.FailureMode != "none" {
			fmCounts[c.FailureMode]++
		}
		for _, rb := range c.RubricRefs {
			rbCounts[rb]++
		}
	}

	return map[string]interface{}{
		"total_cases":              len(r.AllCases),
		"datasets_loaded":          len(r.ByDomainCategory),
		"failure_modes_covered":    len(fmCounts),
		"rubrics_covered":          len(rbCounts),
		"loaded_at":                r.LoadedAt,
	}
}
```

