## (3) LOADER: `pkg/eval/golden/loader.go`

```go
// Package golden loader implementation
package golden

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// LoadGoldenDir discovers all golden_datasets JSON files in a directory tree
// and populates a Registry.
//
// Expected layout:
//   golden_datasets/
//     settlement/
//       correct_cases.json
//       hallucination_cases.json
//       netting_cases.json
//       edge_and_regression_cases.json
//     compliance/
//       kyc_approved_cases.json
//       kyc_rejected_cases.json
//       aml_cases.json
//       edge_cases.json
//     orchestration/
//       valid_and_invalid_cases.json
//     lineage/
//       lineage_cases.json
//     INDEX.json (metadata; optional)
//
// Each JSON file must have structure:
//   {
//     "test_dataset": {
//       "domain": string,
//       "category": string,
//       "cases": [ Case ... ]
//     }
//   }
//
// Returns a populated Registry or error if files are malformed.
func LoadGoldenDir(rootPath string) (*Registry, error) {
	reg := NewRegistry()

	// Find all *_cases.json files
	files, err := ioutil.ReadDir(rootPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read golden_datasets root: %w", err)
	}

	casesFiles := []string{}

	// Walk subdirectories (domain folders)
	for _, entry := range files {
		if !entry.IsDir() {
			continue // Skip files in root; datasets are in subdirs
		}

		domainPath := filepath.Join(rootPath, entry.Name())
		domainFiles, err := ioutil.ReadDir(domainPath)
		if err != nil {
			return nil, fmt.Errorf("failed to read domain %s: %w", entry.Name(), err)
		}

		for _, f := range domainFiles {
			if strings.HasSuffix(f.Name(), "_cases.json") {
				casesFiles = append(casesFiles, filepath.Join(domainPath, f.Name()))
			}
		}
	}

	sort.Strings(casesFiles) // Deterministic order

	// Parse each file
	for _, filePath := range casesFiles {
		ds, err := parseDatasetFile(filePath)
		if err != nil {
			return nil, fmt.Errorf("failed to parse %s: %w", filePath, err)
		}

		if err := reg.Add(ds); err != nil {
			return nil, fmt.Errorf("failed to add dataset %s:%s: %w", ds.Domain, ds.Category, err)
		}
	}

	return reg, nil
}

// parseDatasetFile reads and unmarshals a single golden dataset file.
func parseDatasetFile(filePath string) (*Dataset, error) {
	data, err := ioutil.ReadFile(filePath)
	if err != nil {
		return nil, fmt.Errorf("read file: %w", err)
	}

	// Top-level structure
	var wrapper struct {
		TestDataset *Dataset `json:"test_dataset"`
	}

	if err := json.Unmarshal(data, &wrapper); err != nil {
		return nil, fmt.Errorf("unmarshal: %w", err)
	}

	if wrapper.TestDataset == nil {
		return nil, fmt.Errorf("missing test_dataset key")
	}

	ds := wrapper.TestDataset

	// Validate required fields
	if ds.Domain == "" {
		return nil, fmt.Errorf("missing domain")
	}
	if ds.Category == "" {
		return nil, fmt.Errorf("missing category")
	}

	// Populate derived fields
	ds.TotalCases = len(ds.Cases)
	if ds.CreatedAt.IsZero() {
		ds.CreatedAt = time.Now()
	}

	// Collect failure modes and rubrics
	fmSet := make(map[string]bool)
	rbSet := make(map[string]bool)

	for _, c := range ds.Cases {
		// Ensure case has required fields
		if c.ID == "" {
			return nil, fmt.Errorf("case missing id")
		}

		// Set source if not already set
		if c.Source == "" {
			c.Source = "json_golden"
		}

		if c.FailureMode != "none" && c.FailureMode != "" {
			fmSet[c.FailureMode] = true
		}
		for _, rb := range c.RubricRefs {
			rbSet[rb] = true
		}
	}

	// Sort and populate
	for fm := range fmSet {
		ds.FailureModesCovered = append(ds.FailureModesCovered, fm)
	}
	sort.Strings(ds.FailureModesCovered)

	for rb := range rbSet {
		ds.RubricsCovered = append(ds.RubricsCovered, rb)
	}
	sort.Strings(ds.RubricsCovered)

	return ds, nil
}

// LoadGoldenDirWithMigration attempts to load from a migrated unified directory,
// falling back to system-specific locations if needed.
//
// Search order:
//   1. {rootPath}/golden_datasets/ (unified)
//   2. Fallback to legacy locations (for backward compat)
func LoadGoldenDirWithMigration(rootPath string) (*Registry, error) {
	unifiedPath := filepath.Join(rootPath, "golden_datasets")
	if _, err := os.Stat(unifiedPath); err == nil {
		return LoadGoldenDir(unifiedPath)
	}

	// Fallback: try legacy paths (future)
	return nil, fmt.Errorf("no golden_datasets directory found at %s", unifiedPath)
}
```

