## (4) EVALUATION ADAPTER: `pkg/eval/golden/evaluator.go`

```go
// Package golden evaluator: runs real judges against expected outcomes
package golden

import (
	"fmt"
	"time"

	"github.com/c2siorg/genie/pkg/eval/judges"
)

// EvaluationResult is the outcome of running a Case against actual output.
type EvaluationResult struct {
	// CaseID the case being evaluated
	CaseID string `json:"case_id"`

	// FailureMode the FM-* reference
	FailureMode string `json:"failure_mode"`

	// Pass true if actual output matches expected
	Pass bool `json:"pass"`

	// MatchesExpected detailed match result
	MatchesExpected bool `json:"matches_expected"`

	// JudgeVerdict from applicable judges (e.g., "PASS", "FAIL", "PARTIAL")
	JudgeVerdict string `json:"judge_verdict"`

	// RubricScores rubric evaluation results
	RubricScores []judges.RubricScore `json:"rubric_scores"`

	// Error any evaluation error
	Error string `json:"error,omitempty"`

	// DetectionLatencyMs how long detection took (if failure detected)
	DetectionLatencyMs int64 `json:"detection_latency_ms,omitempty"`

	// Severity detected failure severity
	Severity string `json:"severity,omitempty"`

	// EvaluatedAt timestamp
	EvaluatedAt time.Time `json:"evaluated_at"`
}

// EvaluatorConfig holds judge instances for a domain
type EvaluatorConfig struct {
	// Judges map domain -> Judge instance
	// Example: "settlement" -> ComplianceJudge{...}
	Judges map[string]judges.Judge
}

// Evaluator runs cases against actual outputs using real judges
type Evaluator struct {
	config *EvaluatorConfig
}

// NewEvaluator creates an evaluator with judge instances.
// Example judges: judges.NewComplianceJudge(), judges.NewSettlementJudge(), etc.
func NewEvaluator(config *EvaluatorConfig) *Evaluator {
	if config == nil {
		config = &EvaluatorConfig{Judges: make(map[string]judges.Judge)}
	}
	return &Evaluator{config: config}
}

// Evaluate runs a single Case against actual runtime output.
//
// Steps:
//   1. Look up applicable Judge for the case domain
//   2. Call Judge.Evaluate(case.Input, actualOutput, case.Expected)
//   3. Collect rubric scores and verdict
//   4. Merge with schema-level assertions (field types, nullability)
//   5. Return EvaluationResult (Pass = all rubrics good + schema matches)
//
// actualOutput is a map from real execution (e.g., settlement result, ledger state).
func (e *Evaluator) Evaluate(c *Case, actualOutput map[string]interface{}) *EvaluationResult {
	result := &EvaluationResult{
		CaseID:      c.ID,
		FailureMode: c.FailureMode,
		EvaluatedAt: time.Now(),
	}

	// Get judge for this case's domain
	domain := c.Metadata["domain"]
	judge := e.config.Judges[domain]
	if judge == nil {
		result.Error = fmt.Sprintf("no judge registered for domain %s", domain)
		return result
	}

	// Run judge
	verdict, rubricScores, err := judge.Evaluate(c.Input, actualOutput, c.Expected)
	if err != nil {
		result.Error = fmt.Sprintf("judge evaluation failed: %v", err)
		return result
	}

	result.JudgeVerdict = verdict
	result.RubricScores = rubricScores

	// Verdict -> Pass/Fail
	// PASS: all rubrics >= acceptance_criteria
	// FAIL: any rubric < acceptance_criteria
	// PARTIAL: some rubrics pass, some fail
	result.Pass = (verdict == "PASS")
	result.MatchesExpected = result.Pass

	// Set severity if failure detected
	if !result.Pass {
		result.Severity = c.Metadata["severity"]
		result.DetectionLatencyMs = time.Now().Unix() // Placeholder; judge provides actual
	}

	return result
}

// EvaluateDataset runs all cases in a dataset.
func (e *Evaluator) EvaluateDataset(ds *Dataset, actualOutputs map[string]map[string]interface{}) []EvaluationResult {
	var results []EvaluationResult

	for _, c := range ds.Cases {
		actualOutput := actualOutputs[c.ID]
		if actualOutput == nil {
			actualOutput = make(map[string]interface{})
		}

		result := e.Evaluate(&c, actualOutput)
		results = append(results, *result)
	}

	return results
}

// EvaluateRegistry runs all cases in a registry.
func (e *Evaluator) EvaluateRegistry(reg *Registry, actualOutputs map[string]map[string]interface{}) ([]EvaluationResult, EvaluationStats) {
	var allResults []EvaluationResult
	stats := EvaluationStats{
		TotalCases:   len(reg.AllCases),
		StartTime:    time.Now(),
	}

	for i := range reg.AllCases {
		c := &reg.AllCases[i]
		actualOutput := actualOutputs[c.ID]
		if actualOutput == nil {
			actualOutput = make(map[string]interface{})
		}

		result := e.Evaluate(c, actualOutput)
		allResults = append(allResults, *result)

		if result.Pass {
			stats.PassCount++
		} else {
			stats.FailCount++
		}
	}

	stats.EndTime = time.Now()
	stats.PassRate = float64(stats.PassCount) / float64(stats.TotalCases)

	return allResults, stats
}

// EvaluationStats summarizes evaluation run
type EvaluationStats struct {
	TotalCases int
	PassCount  int
	FailCount  int
	PassRate   float64
	StartTime  time.Time
	EndTime    time.Time
}
```

