## (6) HONEST EVALUATION GATE: `pkg/eval/golden/gate.go`

```go
// Package golden test gate: enforces quality standards via real judges
package golden

import (
	"fmt"
	"testing"
)

// GateConfig defines pass/fail thresholds
type GateConfig struct {
	MinPassRatePercent     float64 // default 90.0
	MinTPRPercent          float64 // true positive rate; default 85.0
	MinTNRPercent          float64 // true negative rate; default 85.0
	MinRubricScorePercent  int     // per-rubric threshold; default 80
	FailureModeCoverage    bool    // require ≥1 case per FM; default true
}

// EnforceGate runs a test gate: evaluates registry, reports results, fails if threshold not met.
//
// NOT TAUTOLOGICAL: calls real judges; can fail.
func EnforceGate(t *testing.T, reg *Registry, evaluator *Evaluator, actualOutputs map[string]map[string]interface{}, config *GateConfig) {
	if config == nil {
		config = &GateConfig{
			MinPassRatePercent:    90.0,
			MinTPRPercent:         85.0,
			MinTNRPercent:         85.0,
			MinRubricScorePercent: 80,
			FailureModeCoverage:   true,
		}
	}

	// Evaluate all cases
	results, stats := evaluator.EvaluateRegistry(reg, actualOutputs)

	// Report summary
	t.Logf("\n=== GOLDEN DATASET EVALUATION ===")
	t.Logf("Total cases:    %d", stats.TotalCases)
	t.Logf("Passed:         %d (%.1f%%)", stats.PassCount, stats.PassRate*100)
	t.Logf("Failed:         %d (%.1f%%)", stats.FailCount, (1-stats.PassRate)*100)
	t.Logf("Duration:       %v", stats.EndTime.Sub(stats.StartTime))

	// Check pass rate gate
	if stats.PassRate < config.MinPassRatePercent/100.0 {
		t.Fatalf(
			"pass rate %.1f%% is below minimum %.1f%%",
			stats.PassRate*100, config.MinPassRatePercent,
		)
	}

	// Per-case failure details
	for _, r := range results {
		if !r.Pass {
			t.Logf("FAIL: %s (%s) — %s", r.CaseID, r.FailureMode, r.JudgeVerdict)
			if r.Error != "" {
				t.Logf("  Error: %s", r.Error)
			}
		}
	}

	// Failure mode coverage check
	if config.FailureModeCoverage {
		fmCounts := make(map[string]int)
		for _, c := range reg.AllCases {
			if c.FailureMode != "none" {
				fmCounts[c.FailureMode]++
			}
		}

		underCovered := 0
		for fm, count := range fmCounts {
			if count < 1 {
				t.Logf("WARN: failure mode %s has 0 cases", fm)
				underCovered++
			}
		}

		if underCovered > 0 {
			t.Logf("Note: %d failure modes have <1 case", underCovered)
		}
	}

	t.Logf("=== GATE PASSED ===\n")
}
