## (8) HOW 'EXPECTED' IS EVALUATED: Matcher Types

**Problem:** `Expected` in unified format is a spec, not a value. At evaluation time, must compare `actual_output` to `expected` assertions.

**Solution:** Matcher types in evaluator:

```go
// Matcher interface: compares actual value to expected assertion
type Matcher interface {
	Match(actual interface{}) bool
	Evidence() string
}

// ExactMatcher: actual == expected
type ExactMatcher struct {
	Expected interface{}
}

func (m *ExactMatcher) Match(actual interface{}) bool {
	return actual == m.Expected
}

// RangeMatcher: actual >= min AND actual <= max
type RangeMatcher struct {
	Min, Max int64
}

func (m *RangeMatcher) Match(actual interface{}) bool {
	v, ok := actual.(int64)
	if !ok {
		return false
	}
	return v >= m.Min && v <= m.Max
}

// NullMatcher: actual is nil
type NullMatcher struct{}

func (m *NullMatcher) Match(actual interface{}) bool {
	return actual == nil
}

// ArrayContainsMatcher: actual array contains value
type ArrayContainsMatcher struct {
	Values []interface{}
}

func (m *ArrayContainsMatcher) Match(actual interface{}) bool {
	arr, ok := actual.([]interface{})
	if !ok {
		return false
	}
	for _, v := range arr {
		for _, want := range m.Values {
			if v == want {
				return true
			}
		}
	}
	return false
}

// Judge.Evaluate() uses these matchers:
func (j *Judge) Evaluate(input, actual, expected map[string]interface{}) (verdict string, scores []Score, err error) {
	for key, expectedVal := range expected {
		actualVal, exists := actual[key]
		if !exists && expectedVal != nil {
			// Missing key = FAIL (unless expected is null)
			return "FAIL", nil, fmt.Errorf("missing key: %s", key)
		}

		matcher := j.buildMatcher(expectedVal)
		if !matcher.Match(actualVal) {
			return "FAIL", nil, fmt.Errorf("mismatch at %s: %s", key, matcher.Evidence())
		}
	}

	return "PASS", []Score{}, nil
}
