## Part 4: Real evaluateTestCase Implementation

```go
// evaluateTestCase routes each case to the appropriate judge and returns TestResult.
//
// PRINCIPLE: A case is worthless unless executed against real logic.
// No pre-baked actual_output; dispatch to judges; honest verdict.
func evaluateTestCase(ctx context.Context, tc GoldenTestCase, judgeRegistry JudgeRegistry) TestResult {
	// Validate case structure
	if tc.ID == "" || tc.FailureMode == "" {
		return TestResult{Pass: false, Error: "missing case ID or FailureMode"}
	}

	// Infer domain from FailureMode (FM-DOMAIN-NNN)
	domain, err := extractDomain(tc.FailureMode)
	if err != nil {
		return TestResult{Pass: false, Error: fmt.Sprintf("invalid FailureMode: %v", err)}
	}

	// Dispatch to domain-specific judge
	var verdict judges.Verdict
	switch domain {
	case DomainSettlement:
		input, err := buildSettlementJudgeInput(tc)
		if err != nil {
			return TestResult{Pass: false, Error: fmt.Sprintf("build settlement input: %v", err)}
		}
		judge := judgeRegistry.GetSettlementJudge()
		if judge == nil {
			return TestResult{Pass: false, Error: "SettlementJudge not initialized"}
		}
		var evalErr error
		verdict, evalErr = judge.Evaluate(ctx, input)
		if evalErr != nil {
			return TestResult{Pass: false, Error: fmt.Sprintf("judge evaluate: %v", evalErr)}
		}

	case DomainCompliance:
		input, err := buildComplianceJudgeInput(tc)
		if err != nil {
			return TestResult{Pass: false, Error: fmt.Sprintf("build compliance input: %v", err)}
		}
		judge := judgeRegistry.GetComplianceJudge()
		if judge == nil {
			return TestResult{Pass: false, Error: "ComplianceJudge not initialized"}
		}
		var evalErr error
		verdict, evalErr = judge.Evaluate(ctx, input)
		if evalErr != nil {
			return TestResult{Pass: false, Error: fmt.Sprintf("judge evaluate: %v", evalErr)}
		}

	case DomainOrchestration:
		input, err := buildOrchestrationJudgeInput(tc)
		if err != nil {
			return TestResult{Pass: false, Error: fmt.Sprintf("build orchestration input: %v", err)}
		}
		judge := judgeRegistry.GetOrchestrationJudge()
		if judge == nil {
			return TestResult{Pass: false, Error: "OrchestrationJudge not initialized"}
		}
		var evalErr error
		verdict, evalErr = judge.Evaluate(ctx, input)
		if evalErr != nil {
			return TestResult{Pass: false, Error: fmt.Sprintf("judge evaluate: %v", evalErr)}
		}

	case DomainLineageAudit:
		input, err := buildLineageJudgeInput(tc)
		if err != nil {
			return TestResult{Pass: false, Error: fmt.Sprintf("build lineage input: %v", err)}
		}
		judge := judgeRegistry.GetLineageJudge()
		if judge == nil {
			return TestResult{Pass: false, Error: "LineageJudge not initialized"}
		}
		var evalErr error
		verdict, evalErr = judge.Evaluate(ctx, input)
		if evalErr != nil {
			return TestResult{Pass: false, Error: fmt.Sprintf("judge evaluate: %v", evalErr)}
		}

	default:
		// Deterministic-only domains (Merchant/Customer, Agent Behavior)
		return evaluateDeterministic(tc)
	}

	// Extract result from verdict
	return TestResult{
		Pass:   verdict.Pass,
		Error:  "",
		Score:  verdict.Score,
		Reason: verdict.Reason,
	}
}

// JudgeRegistry holds references to all judges (singleton or dependency-injected).
type JudgeRegistry interface {
	GetSettlementJudge() judges.Judge
	GetComplianceJudge() judges.Judge
	GetOrchestrationJudge() judges.Judge
	GetLineageJudge() judges.Judge
}

// extractDomain parses "FM-DOMAIN-NNN" to get DOMAIN.
func extractDomain(failureMode string) (FailureModeDomain, error) {
	parts := strings.Split(failureMode, "-")
	if len(parts) < 2 {
		return "", fmt.Errorf("invalid FailureMode format: %s", failureMode)
	}

	domainCode := parts[1]
	switch domainCode {
	case "SE":
		return DomainSettlement, nil
	case "CO":
		return DomainCompliance, nil
	case "OR":
		return DomainOrchestration, nil
	case "LA":
		return DomainLineageAudit, nil
	case "MC":
		return DomainMerchantCustomer, nil
	case "AB":
		return DomainAgentBehavior, nil
	default:
		return "", fmt.Errorf("unknown domain code: %s", domainCode)
	}
}

// evaluateDeterministic handles Merchant/Customer and Agent Behavior domains
// without delegating to judges (no judges exist for these yet).
func evaluateDeterministic(tc GoldenTestCase) TestResult {
	// For now, check basic consistency:
	// - Input and Expected must be non-empty
	// - Metadata must have domain and severity
	if len(tc.Input) == 0 || len(tc.Expected) == 0 {
		return TestResult{Pass: false, Error: "empty input or expected output"}
	}
	if tc.Metadata["domain"] == "" || tc.Metadata["severity"] == "" {
		return TestResult{Pass: false, Error: "missing required metadata"}
	}

	// Pass—no deeper validation yet (placeholder for future MC/AB judges)
	return TestResult{Pass: true, Error: ""}
}
