		settlementJudge:   judges.NewMockSettlementJudge(),
		complianceJudge:   judges.NewMockComplianceJudge(),
		orchestrationJudge: judges.NewMockOrchestrationJudge(),
		lineageJudge:      judges.NewMockLineageJudge(),
	}

	var passCount, failCount int
	for _, tc := range GoldenDataset {
		result := evaluateTestCase(ctx, tc, registry)
		if result.Pass {
			passCount++
		} else {
			failCount++
			t.Logf("FAIL: %s (%s) - %s", tc.ID, tc.FailureMode, result.Error)
		}
	}

	passRate := float64(passCount) / float64(len(GoldenDataset))
	if passRate < 0.85 {
		t.Fatalf("GATE FAILED: pass rate %.1f%% < 85%% threshold", passRate*100)
	}

	t.Logf("GATE PASSED: %d/%d cases (%.1f%%)", passCount, len(GoldenDataset), passRate*100)
}
